def specs(suites):
 for suite in suites:
  yield from suite.get('specs',[]);yield from specs(suite.get('suites',[]))
def key(spec,test):return (spec['file'],test.get('projectName',''),spec['title'])
def attachments(spec,test):
 out=[]
 for result in test['results']:
  for item in result.get('attachments',[]):
   data=base64.b64decode(item['body']) if 'body'in item else Path(item['path']).read_bytes() if 'path'in item and Path(item['path']).is_file() else None
   if data is not None:out.append(dict(file=spec['file'],test=spec['title'],name=item['name'],contentType=item.get('contentType'),sha256=hashlib.sha256(data).hexdigest(),**({'data':json.loads(data)} if item.get('contentType')=='application/json' else {'base64':base64.b64encode(data).decode()})))
 return out
